Got you. Here is the standard boilerplate using `sync.Mutex` as a named field to protect state.

```go
package main

import (
	"fmt"
	"sync"
)

type SafeState struct {
	mu   sync.Mutex // Named field is generally preferred over embedding to avoid exporting Lock()
	data int
}

func (s *SafeState) Update(val int) {
	s.mu.Lock()
	defer s.mu.Unlock() // Use defer to ensure unlock even if code panics or returns early

	s.data = val
}

func (s *SafeState) Read() int {
	s.mu.Lock()
	defer s.mu.Unlock()

	return s.data
}

func main() {
	s := &SafeState{}

	// Example usage
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		s.Update(42)
	}()

	wg.Wait()
	fmt.Println(s.Read())
}
```

**Quick tip:** Keep the critical section (code between `Lock` and `Unlock`) as small as possible to maximize concurrency.
